            counts[item] += 1

    # Round 1: Report Noisy Max over all candidates
    r1_scores = {c: counts[c] + rng.laplace(0.0, scale) for c in candidates}
    first_winner = max(candidates, key=lambda c: r1_scores[c])

    # Round 2: Report Noisy Max over remaining candidates
    rem_candidates = [c for c in candidates if c != first_winner]
    r2_scores = {
        c: counts[c] + rng.laplace(0.0, scale) for c in rem_candidates
    }
    second_winner = max(rem_candidates, key=lambda c: r2_scores[c])

    return [first_winner, second_winner]

